import{_ as r,o as t,c as e,a5 as i}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"跨域问题","description":"","frontmatter":{"title":"跨域问题","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端接口开发入门/跨域问题.md","filePath":"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端接口开发入门/跨域问题.md"}'),p={name:"posts/java快速入门/第六部分：Spring 生态/02-Spring Boot/B-接口开发/后端接口开发入门/跨域问题.md"};function a(n,o,s,g,u,l){return t(),e("div",null,[...o[0]||(o[0]=[i('<div><p>前端测试接口，因为端口的不同还是出现了跨域问题</p><p>通过<code>@CrossOrigin</code>解决，因为方便，但是不是很好，还是单独配置一下过滤器比较好；</p><p>这个<code>@</code>CrossOrigin还可以加到控制器类上，类中的所有方法就不用加了；</p><p>注解@CrossOrigin详解</p><p>huayang183</p><p>于 2020-10-25 16:42:30 发布</p><p>75851 收藏 329 分类专栏： SpringBoot 版权</p><p>SpringBoot 专栏收录该内容 186 篇文章6 订阅 订阅专栏 注解@CrossOrigin 出于安全原因，浏览器禁止Ajax调用驻留在当前原点之外的资源。例如，当你在一个标签中检查你的银行账户时，你可以在另一个选项卡上拥有EVILL网站。来自EVILL的脚本不能够对你的银行API做出Ajax请求（从你的帐户中取出钱！）使用您的凭据。</p><p>跨源资源共享（CORS）是由大多数浏览器实现的W3C规范，允许您灵活地指定什么样的跨域请求被授权，而不是使用一些不太安全和不太强大的策略，如IFRAME或JSONP。</p><p>一、跨域(CORS)支持： Spring Framework 4.2 GA为CORS提供了第一类支持，使您比通常的基于过滤器的解决方案更容易和更强大地配置它。所以springMVC的版本要在4.2或以上版本才支持@CrossOrigin</p><p>二、使用方法： 1、controller配置CORS 1.1、controller方法的CORS配置</p><p>你可以向@RequestMapping注解处理程序方法添加一个@CrossOrigin注解，以便启用CORS（默认情况下，@CrossOrigin允许在@RequestMapping注解中指定的所有源和HTTP方法）：</p><p>@RestController @RequestMapping(&quot;/account&quot;) public class AccountController { @CrossOrigin @GetMapping(&quot;/{id}&quot;) public Account retrieve(@PathVariable Long id) { // ... } @DeleteMapping(&quot;/{id}&quot;) public void remove(@PathVariable Long id) { // ... } } 其中@CrossOrigin中的2个参数：</p><p>origins： 允许可访问的域列表 maxAge:准备响应前的缓存持续的最大时间（以秒为单位）。 1.2、为整个controller启用@CrossOrigin</p><p>@CrossOrigin(origins = &quot;<a href="http://domain2.com" target="_blank" rel="noreferrer">http://domain2.com</a>&quot;, maxAge = 3600) @RestController @RequestMapping(&quot;/account&quot;) public class AccountController { @GetMapping(&quot;/{id}&quot;) public Account retrieve(@PathVariable Long id) { // ... } @DeleteMapping(&quot;/{id}&quot;) public void remove(@PathVariable Long id) { // ... } }</p><p>在这个例子中，对于retrieve()和remove()处理方法都启用了跨域支持，还可以看到如何使用@CrossOrigin属性定制CORS配置。</p><p>1.3、同时使用controller和方法级别的CORS配置</p><p>Spring将合并两个注释属性以创建合并的CORS配置。</p><p>@CrossOrigin(maxAge = 3600) @RestController @RequestMapping(&quot;/account&quot;) public class AccountController { @CrossOrigin(origins = &quot;<a href="http://domain2.com" target="_blank" rel="noreferrer">http://domain2.com</a>&quot;) @GetMapping(&quot;/{id}&quot;) public Account retrieve(@PathVariable Long id) { // ... } @DeleteMapping(&quot;/{id}&quot;) public void remove(@PathVariable Long id) { // ... } }</p><p>1.4、如果正在使用Spring Security</p><p>请确保在Spring安全级别启用CORS，并允许它利用Spring MVC级别定义的配置。</p><p>@EnableWebSecurity public class WebSecurityConfig extends WebSecurityConfigurerAdapter { @Override protected void configure(HttpSecurity http) throws Exception { http.cors().and()... } } 2、全局CORS配置 除了细粒度、基于注释的配置之外，您还可能需要定义一些全局CORS配置。这类似于使用筛选器，但可以声明为Spring MVC并结合细粒度@CrossOrigin配置。默认情况下，所有origins and GET, HEAD and POST methods是允许的。</p><p>JavaConfig使整个应用程序的CORS简化为：</p><p>@Configuration @EnableWebMvc public class WebConfig extends WebMvcConfigurerAdapter { @Override public void addCorsMappings(CorsRegistry registry) { registry.addMapping(&quot;/**&quot;); } } 如果你正在使用Spring Boot，建议将WebMvcConfigurer bean声明如下：</p><p>@Configuration public class MyConfiguration { @Bean public WebMvcConfigurer corsConfigurer() { return new WebMvcConfigurerAdapter() { @Override public void addCorsMappings(CorsRegistry registry) { registry.addMapping(&quot;/**&quot;); } }; } } 你可以轻松地更改任何属性，以及仅将此CORS配置应用到特定的路径模式：</p><p>@Override public void addCorsMappings(CorsRegistry registry) { registry.addMapping(&quot;/api/**&quot;) .allowedOrigins(&quot;<a href="http://domain2.com" target="_blank" rel="noreferrer">http://domain2.com</a>&quot;) .allowedMethods(&quot;PUT&quot;, &quot;DELETE&quot;) .allowedHeaders(&quot;header1&quot;, &quot;header2&quot;, &quot;header3&quot;) .exposedHeaders(&quot;header1&quot;, &quot;header2&quot;) .allowCredentials(false).maxAge(3600); } 如果你正在使用Spring Security，请确保在Spring安全级别启用CORS，并允许它利用Spring MVC级别定义的配置。 3、XML命名空间 还可以将CORS与MVC XML命名空间配置。</p><p>a、如果整个项目所有方法都可以访问，则可以这样配置</p><p>此最小XML配置使CORS在/**路径模式具有与JavaConfig相同的缺省属性：</p><p>&lt;mvc:cors&gt; &lt;mvc:mapping path=&quot;/<strong>&quot; /&gt; &lt;/mvc:cors&gt; 其中* 表示匹配到下一层；</strong> 表示后面不管有多少层，都能匹配。</p><p>如：</p><p>&lt;mvc:cors&gt; &lt;mvc:mapping path=&quot;/api/*&quot;/&gt; &lt;/mvc:cors&gt; 这个可以匹配到的路径有：</p><p>/api/aaa</p><p>/api/bbbb</p><p>不能匹配的：</p><p>/api/aaa/bbb</p><p>因为* 只能匹配到下一层路径，如果想后面不管多少层都可以匹配，配置如下：</p><p>&lt;mvc:cors&gt; &lt;mvc:mapping path=&quot;/api/**&quot;/&gt; &lt;/mvc:cors&gt; 注：其实就是一个()变成两个(*)</p><p>b、也可以用定制属性声明几个CORS映射：</p><p>&lt;mvc:cors&gt; &lt;mvc:mapping path=&quot;/api/<strong>&quot; allowed-origins=&quot;<a href="http://domain1.com" target="_blank" rel="noreferrer">http://domain1.com</a>, <a href="http://domain2.com" target="_blank" rel="noreferrer">http://domain2.com</a>&quot; allowed-methods=&quot;GET, PUT&quot; allowed-headers=&quot;header1, header2, header3&quot; exposed-headers=&quot;header1, header2&quot; allow-credentials=&quot;false&quot; max-age=&quot;123&quot; /&gt; &lt;mvc:mapping path=&quot;/resources/</strong>&quot; allowed-origins=&quot;<a href="http://domain1.com" target="_blank" rel="noreferrer">http://domain1.com</a>&quot; /&gt; &lt;/mvc:cors&gt; 请求路径有/api/，方法示例如下：</p><p>@RequestMapping(&quot;/api/crossDomain&quot;) @ResponseBody public String crossDomain(HttpServletRequest req, HttpServletResponse res, String name){ …… …… } c、如果使用Spring Security，不要忘记在Spring安全级别启用CORS：</p><p>&lt;http&gt; &lt;!-- Default to Spring MVC&#39;s CORS configuration --&gt; &lt;cors /&gt; ... &lt;/http&gt; 4、How does it work? CORS请求（包括预选的带有选项方法）被自动发送到注册的各种HandlerMapping。它们处理CORS准备请求并拦截CORS简单和实际请求，这得益于CorsProcessor实现（默认情况下默认DefaultCorsProcessor处理器），以便添加相关的CORS响应头（如Access-Control-Allow-Origin）。CorsConfiguration允许您指定CORS请求应该如何处理：允许origins, headers, methods等。</p><p>a、AbstractHandlerMapping#setCorsConfiguration()允许指定一个映射，其中有几个CorsConfiguration映射在路径模式上，比如/api/**。</p><p>b、子类可以通过重写AbstractHandlerMapping类的getCorsConfiguration(Object, HttpServletRequest)方法来提供自己的CorsConfiguration。</p><p>c、处理程序可以实现CorsConfigurationSource接口（如ResourceHttpRequestHandler），以便为每个请求提供一个CorsConfiguration。</p><p>5、基于过滤器的CORS支持 作为上述其他方法的替代，Spring框架还提供了CorsFilter。在这种情况下，不用使用@CrossOrigin或WebMvcConfigurer#addCorsMappings(CorsRegistry),，例如，可以在Spring Boot应用程序中声明如下的过滤器：</p><p>@Configuration public class MyConfiguration { @Bean public FilterRegistrationBean corsFilter() { UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource(); CorsConfiguration config = new CorsConfiguration(); config.setAllowCredentials(true); config.addAllowedOrigin(&quot;<a href="http://domain1.com" target="_blank" rel="noreferrer">http://domain1.com</a>&quot;); config.addAllowedHeader(&quot;<em>&quot;); config.addAllowedMethod(&quot;</em>&quot;); source.registerCorsConfiguration(&quot;/**&quot;, config); FilterRegistrationBean bean = new FilterRegistrationBean(new CorsFilter(source)); bean.setOrder(0); return bean; } } 三、spring注解@CrossOrigin不起作用的原因 1、是springMVC的版本要在4.2或以上版本才支持@CrossOrigin 2、非@CrossOrigin没有解决跨域请求问题，而是不正确的请求导致无法得到预期的响应，导致浏览器端提示跨域问题。 3、在Controller注解上方添加@CrossOrigin注解后，仍然出现跨域问题，解决方案之一就是：</p><p>在@RequestMapping注解中没有指定Get、Post方式，具体指定后，问题解决。</p><p>类似代码如下： @CrossOrigin @RestController public class person{ @RequestMapping(method = RequestMethod.GET) public String add() { // 若干代码 } } 四、参考文章 ———————————————— 版权声明：本文为CSDN博主「huayang183」的原创文章，遵循CC 4.0 BY-SA版权协议，转载请附上原文出处链接及本声明。 原文链接：<a href="https://blog.csdn.net/qq_18671415/article/details/109275495" target="_blank" rel="noreferrer">https://blog.csdn.net/qq_18671415/article/details/109275495</a></p><p>==CORS 跨域共享== ==跨源资源共享(Cross-origin resource sharing, CORS)是由大多数浏览器实现的W3C规范，它允许您以灵活的方式指定哪种跨域请求被授权，而不是使用一些不太安全、功能不太强大的方法，比如IFRAME或JSONP。==</p><p>==Spring BOOT== ==从4.2开始，Spring MVC已支持CORS。==</p><p>==@CrossOrigin== ==在Spring Boot中使用带有@CrossOrigin注释的controller方法CORS配置，不需要任何特定的配置。==</p><p>==@CrossOrigin注解可以在类上使用，也可以在方法上使用，如：==</p><p>==@CrossOrigin(origins = &quot;<a href="http://domain2.com" target="_blank" rel="noreferrer">http://domain2.com</a>&quot;, maxAge = 3600)== ==@RestController== ==@RequestMapping(&quot;/account&quot;)== ==public class AccountController {==</p><p>==@GetMapping(&quot;/{id}&quot;)== ==public Account retrieve(@PathVariable Long id) {== ==// ...== ==}==</p><p>==@DeleteMapping(&quot;/{id}&quot;)== ==public void remove(@PathVariable Long id) {== ==// ...== ==}== ==}== ==常用的属性有2个，分别是origins和maxAge，下面分别解释下：==</p><p>==origins 是一个字符串数组的类型（String []），用于表示那些域名可以访问此接口/映射。多个域名之间用逗号“，”隔开，如果想向所有网址开放，可以直接填写星号“*”。== ==maxAge 还没有找到官方的说明，其他开发者解释为“预请求的结果的有效期”，即COOKIE的有效期，单位是秒。== ==如果只在方法上或者类上使用@CrossOrigin注解，则默认该映射接受所有的网站发送过来的请求、接受所有类型的http请求和接受所有的不同内容的头部信息（Header），如：==</p><p>==@RestController== ==@RequestMapping(&quot;/account&quot;)== ==public class AccountController {==</p><p>==@CrossOrigin== ==@GetMapping(&quot;/{id}&quot;)== ==public Account retrieve(@PathVariable Long id) {== ==// ...== ==}==</p><p>==@DeleteMapping(&quot;/{id}&quot;)== ==public void remove(@PathVariable Long id) {== ==// ...== ==}== ==}== ==@CrossOrigin可以同时在类上、方法上同时使用，来控制不同网站访问不同的映射，如：==</p><p>==@CrossOrigin(maxAge = 3600)== ==@RestController== ==@RequestMapping(&quot;/account&quot;)== ==public class AccountController {==</p><p>==@CrossOrigin(&quot;<a href="http://domain2.com" target="_blank" rel="noreferrer">http://domain2.com</a>&quot;)== ==@GetMapping(&quot;/{id}&quot;)== ==public Account retrieve(@PathVariable Long id) {== ==// ...== ==}==</p><p>==@DeleteMapping(&quot;/{id}&quot;)== ==public void remove(@PathVariable Long id) {== ==// ...== ==}== ==}== ==remove方法可以被所有网站的访问，retrieve方法只接受<a href="http://domain2.xn--com-yw3ej13if4m09gqsjzu3anpi" target="_blank" rel="noreferrer">http://domain2.com网站发送的请求</a>。==</p><p>==全局CORS配置== ==全局CORS配置可以通过注册一个WebMvcConfigurer bean并使用自定义的addcorsmapping (CorsRegistry)方法来定义，如:==</p><p>==@Configuration== ==public class MyConfiguration {==</p><p>==@Bean== ==public WebMvcConfigurer corsConfigurer() {== ==return new WebMvcConfigurer() {== ==@Override== ==public void addCorsMappings(CorsRegistry registry) {== ==registry.addMapping(&quot;/api/**&quot;);== ==}== ==};== ==}== ==}==</p></div>',1)])])}const C=r(p,[["render",a]]);export{d as __pageData,C as default};
